SET NAMES utf8mb4;
SET time_zone = '+09:00';
INSERT INTO seed_metadata(seed,data_class) VALUES(290613,'SYNTHETIC') ON DUPLICATE KEY UPDATE data_class=VALUES(data_class);
INSERT INTO pos_stores(property_id,store_id,store_name,store_category,seat_capacity,open_time,close_time,is_active,is_synthetic,source_updated_at) VALUES
