INSERT INTO pos_orders(property_id,order_id,store_id,pos_customer_ref,ordered_at,check_opened_at,check_closed_at,guest_count,service_period,order_status,gross_amount,discount_amount,refund_amount,net_amount,payment_status,payment_amount,void_flag,data_period_status,is_forecast,is_synthetic,source_updated_at)
WITH d AS (SELECT a.n+10*b.n+100*c.n+1000*e.n+10000*f.n AS n FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) e CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) f)
SELECT 'SYNTHETIC_HOTEL_001',CONCAT('PO-',LPAD(n+1,8,'0')),CONCAT('PS-0',1+MOD(n*7+n*n,9)),CASE WHEN MOD(n,5)<>0 THEN CONCAT('PC-',LPAD(1+MOD(n*7919,11475),8,'0')) END,TIMESTAMP('2025-01-01')+INTERVAL MOD(n*37+n*n,577) DAY+INTERVAL (8+MOD(n*11,14)) HOUR,TIMESTAMP('2025-01-01')+INTERVAL MOD(n*37+n*n,577) DAY+INTERVAL (8+MOD(n*11,14)) HOUR,TIMESTAMP('2025-01-01')+INTERVAL MOD(n*37+n*n,577) DAY+INTERVAL (9+MOD(n*11,14)) HOUR,1+MOD(n,6),CASE WHEN MOD(n,3)=0 THEN 'DINNER' WHEN MOD(n,3)=1 THEN 'LUNCH' ELSE 'BREAKFAST' END,'PAID',30000+MOD(n*97,180000),CASE WHEN MOD(n,8)=0 THEN 5000 ELSE 0 END,0,30000+MOD(n*97,180000)-CASE WHEN MOD(n,8)=0 THEN 5000 ELSE 0 END,'PAID',30000+MOD(n*97,180000)-CASE WHEN MOD(n,8)=0 THEN 5000 ELSE 0 END,false,'SYNTHETIC_ACTUAL_LIKE',false,true,'2026-08-01 00:00:00.000' FROM d;
INSERT INTO pos_service_periods(property_id,service_period_id,store_id,business_date,service_period,seat_capacity,open_minutes,covers,seat_hours_available,data_period_status,is_forecast,is_synthetic,source_updated_at,seat_hours_used)
WITH d AS (SELECT a.n+10*b.n+100*c.n AS n FROM (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) a CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) b CROSS JOIN (SELECT 0 n UNION ALL SELECT 1 UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5 UNION ALL SELECT 6 UNION ALL SELECT 7 UNION ALL SELECT 8 UNION ALL SELECT 9) c), s AS (SELECT store_id,seat_capacity FROM pos_stores)
SELECT 'SYNTHETIC_HOTEL_001',1+d.n+1000*row_number() over(),s.store_id,DATE_ADD('2025-01-01',INTERVAL d.n DAY),p.period,s.seat_capacity,CASE p.period WHEN 'BREAKFAST' THEN 180 WHEN 'LUNCH' THEN 240 ELSE 300 END,MOD(d.n*17+ascii(right(s.store_id,1))*7, s.seat_capacity*2),s.seat_capacity*(CASE p.period WHEN 'BREAKFAST' THEN 3 WHEN 'LUNCH' THEN 4 ELSE 5 END),'SYNTHETIC_ACTUAL_LIKE',false,true,'2026-08-01 00:00:00.000',ROUND(s.seat_capacity*(0.20 + (MOD(d.n + LENGTH(s.store_id),40)/100)),2) FROM d CROSS JOIN s CROSS JOIN (SELECT 'BREAKFAST' period UNION ALL SELECT 'LUNCH' UNION ALL SELECT 'DINNER') p WHERE d.n<577;
INSERT INTO pos_order_items(property_id,order_item_id,order_id,item_code,item_category,quantity,unit_price,gross_amount,discount_amount,net_amount,is_synthetic,source_updated_at)
WITH i AS (SELECT 1 n UNION ALL SELECT 2 UNION ALL SELECT 3 UNION ALL SELECT 4 UNION ALL SELECT 5),
base AS (SELECT o.property_id,o.order_id,i.n,1+MOD(CAST(SUBSTRING(o.order_id,4) AS UNSIGNED)+i.n,3) AS qty,10000+MOD(CAST(SUBSTRING(o.order_id,4) AS UNSIGNED)*97+i.n*1300,40000) AS price FROM pos_orders o CROSS JOIN i WHERE o.order_status IN ('PAID','PARTIAL_REFUND','REFUNDED') AND MOD(CAST(SUBSTRING(o.order_id,4) AS UNSIGNED)+i.n,7) <> 0)
SELECT property_id,CONCAT('OI-',SUBSTRING(order_id,4),'-',LPAD(n,2,'0')),order_id,CONCAT('ITEM-',LPAD(1+MOD(CAST(SUBSTRING(order_id,4) AS UNSIGNED)*17+n,80),3,'0')),CASE MOD(CAST(SUBSTRING(order_id,4) AS UNSIGNED)+n,4) WHEN 0 THEN 'FOOD' WHEN 1 THEN 'BEVERAGE' WHEN 2 THEN 'ALCOHOL' ELSE 'MERCH' END,qty,price,qty*price,CASE WHEN MOD(CAST(SUBSTRING(order_id,4) AS UNSIGNED)+n,11)=0 THEN FLOOR(qty*price/10) ELSE 0 END,qty*price-CASE WHEN MOD(CAST(SUBSTRING(order_id,4) AS UNSIGNED)+n,11)=0 THEN FLOOR(qty*price/10) ELSE 0 END,true,'2026-08-01 00:00:00.000' FROM base;
